INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_may_waitlist_closed', 'u_ella', 'people_ops', 'registration_closed', 'sub_signup_watch', 'May accessibility workshop waitlist closed', 'The May workshop closed at 38 seats after two duplicate registrations were removed. The attendance export contains department totals only.', '{"registered":38,"duplicates_removed":2,"event_ref":"A11Y-MAY"}', '2026-05-16T03:12:44Z', 1);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_june_table_mix_review', 'u_ella', 'people_ops', 'facilitation_review', 'sub_signup_watch', 'June table-mix review completed', 'Facilitators reported that tables with at least three functions finished the exercise on time; alphabetical seating produced two uneven groups.', '{"event_ref":"MIX-JUN","minimum_functions":3,"alphabetical_groups_flagged":2}', '2026-06-26T07:26:10Z', 1);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_july_menu_audit_closed', 'u_ella', 'people_ops', 'case_closed', 'sub_signup_watch', 'July catering control audit closed', 'The July offsite caterer supplied sealed special meals, separate utensils, and a named service lead. The follow-up case is closed.', '{"case_id":"CAT-0722","sealed_meals":true,"separate_utensils":true,"status":"closed"}', '2026-07-23T08:42:31Z', 1);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_april_attendance_closed', 'u_ella', 'people_ops', 'attendance_closeout', 'sub_signup_watch', 'April salon attendance reconciled', 'The spring salon closed with 46 checked-in attendees from 58 registrations. Six participant copies remain in the learning cabinet.', '{"registered":58,"checked_in":46,"surplus_books":6,"event_ref":"SALON-APR"}', '2026-05-12T02:21:46Z', 1);
INSERT INTO notifications (notification_id, user_id, source, type, subscription_id, title, body, payload_json, created_at, read) VALUES ('ntf_riverside_layout_limit', 'u_ella', 'review_platform', 'capacity_change', 'sub_venue_capacity_watch', 'Riverside stage layout changes capacity', 'The accessible discussion layout is now capped at 64 seats after two wheelchair turning areas were added; the brochure capacity is no longer valid for that setup.', '{"venue":"Riverside Room","layout":"accessible_discussion","usable_capacity":64,"brochure_capacity":82}', '2026-06-03T01:39:27Z', 1);
